    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (6, 9) or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0, r1 = min(y for y, x in comp), max(y for y, x in comp)
            c0, c1 = min(x for y, x in comp), max(x for y, x in comp)
            if r1 - r0 < 2 or c1 - c0 < 2:
                continue
            perimeter = {(y, x) for y in range(r0, r1 + 1) for x in range(c0, c1 + 1)
                         if y in (r0, r1) or x in (c0, c1)}
            if set(comp) != perimeter:
                continue
            interior = [(y, x) for y in range(r0 + 1, r1) for x in range(c0 + 1, c1)]
            # Small framed regions receive 7; larger interiors receive 2.
            fill = 2 if len(interior) >= 16 else 7
            for y, x in interior:
                out[y][x] = fill
    return out
